import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

@Controller('api/v1')
export class FnSfr03602Controller {
  @Post('/messages/:messageId/read')
  @HttpCode(200)
  async readMessage(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const messageId = req.params['messageId'];
    if (!/^[0-9]+$/.test(messageId)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '메시지 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      // 본인 수신 행만 갱신한다. 이미 열람한 경우 최초 열람 시각을 유지한다.
      const rows = await db.query(
        `UPDATE message_recipient
         SET read_at = COALESCE(read_at, now()),
             updated_at = now()
         WHERE message_id = CAST(:messageId AS bigint)
           AND recipient_id = CAST(:userId AS bigint)
         RETURNING read_at AS "readAt"`,
        { messageId, userId: user.id },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'MESSAGE_NOT_FOUND', '본인이 수신한 메시지를 찾을 수 없습니다.');
      }
      return { readAt: rows[0].readAt };
    });
  }
}

