import { useState } from 'react';
import {
  call,
  Band,
  DataTable,
  DateText,
  Drawer,
  Field,
  Form,
  LookupSelect,
  RefName,
  Tiles,
} from '../kit';
import type { PageProps, Row } from '../kit';

export default function FnSfr03602Page({ role, notify }: PageProps) {
  const [open, setOpen] = useState(false);
  const [messageId, setMessageId] = useState<number | string>('');
  const [results, setResults] = useState<Row[]>([]);

  const openDrawer = () => {
    setMessageId('');
    setOpen(true);
  };

  const submit = async () => {
    if (messageId === '' || messageId === null || messageId === undefined) {
      throw new Error('열람할 메시지를 선택하세요.');
    }
    const res = await call('POST', `/messages/${messageId}/read`, role, {});
    setResults((prev) => [
      { messageId, readAt: res['readAt'] },
      ...prev.filter((r) => r['messageId'] !== messageId),
    ]);
    notify('수신 확인 처리했습니다.');
    setOpen(false);
  };

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>수신 확인</h2>
        <Tiles items={[['처리 건수', results.length]]} />
      </section>
      <section className="box span-8">
        <h2>열람 내역</h2>
        <Band total={results.length}>
          <button type="button" onClick={openDrawer}>메시지 열람</button>
        </Band>
        <DataTable
          columns={[
            {
              key: 'messageId',
              label: '메시지',
              render: (row) => <RefName table="message" role={role} value={row['messageId']} />,
            },
            {
              key: 'readAt',
              label: '수신 확인 일시',
              render: (row) => <DateText value={row['readAt']} time />,
            },
          ]}
          rows={results}
          empty="열람 처리한 메시지가 없습니다."
        />
      </section>
      {open && (
        <Drawer title="메시지 열람" onClose={() => setOpen(false)}>
          <Form onSubmit={submit} submit="열람 처리">
            <Field label="메시지" required wide>
              <LookupSelect
                table="message"
                role={role}
                value={messageId}
                onChange={setMessageId}
                placeholder="메시지 선택"
              />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
